import React, { useEffect, useState } from 'react';
import { useLanguage } from '../context/LanguageContext';

const Home = () => {
  const { t, appData } = useLanguage();
  const [dialoguesPreview, setDialoguesPreview] = useState([]);
  const [storiesPreview, setStoriesPreview] = useState([]);
  const [flashcardsPreview, setFlashcardsPreview] = useState([]);

  const loadData = async () => {
    try {
      // For now, use mock data since we're in React development mode
      const mockData = {
        preview: {
          dialogues: {
            title: 'Diálogos Reais',
            description: 'Pratique com conversas do dia a dia'
          },
          stories: {
            title: 'Histórias Envolventes', 
            description: 'Aprenda através de narrativas cativantes'
          },
          flashcards: {
            title: 'Flashcards Inteligentes',
            description: 'Memorize vocabulário de forma eficiente'
          }
        }
      };
      setDialoguesPreview([mockData.preview.dialogues]);
      setStoriesPreview([mockData.preview.stories]);
      setFlashcardsPreview([mockData.preview.flashcards]);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  useEffect(() => {
    if (appData) {
      // Load preview data
      setDialoguesPreview(appData.dialogues?.slice(0, 3) || []);
      setStoriesPreview(appData.stories?.slice(0, 3) || []);
      setFlashcardsPreview(appData.flashcards?.slice(0, 3) || []);
    } else {
      loadData();
    }
  }, [appData]);

  return (
    <div className="home-page">
      {/* Hero Section */}
      <section className="hero">
        <div className="hero-content">
          <h1 className="hero-title">
            {t('heroTitle', 'Learn languages naturally and fun')}
          </h1>
          <p className="hero-subtitle">
            {t('heroSubtitle', 'Master new languages through real dialogues, engaging stories and smart flashcards.')}
          </p>
          <div className="hero-buttons">
            <button className="btn btn-solid">
              {t('btnStartNow', 'Start Now')}
            </button>
            <button className="btn btn-outline">
              {t('btnLearnMore', 'Learn More')}
            </button>
          </div>
        </div>
        <div className="hero-image">
          <i className="fas fa-globe-americas"></i>
        </div>
      </section>

      {/* Dialogues Container */}
      <section className="content-container" id="dialogues-container">
        <div className="container-header">
          <h2>
            <i className="fas fa-comments"></i> 
            <span>{t('navDialogues', 'Dialogues')}</span>
          </h2>
          <p>{t('featureDialoguesDesc', 'Learn with authentic conversations in everyday situations.')}</p>
        </div>
        <div className="content-wrapper">
          <div className="feature-image">
            <img 
              src="https://images.unsplash.com/photo-1577896851231-70ef18881754?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1170&q=80" 
              alt="People having a conversation"
            />
          </div>
          <div className="preview-example">
            <div id="dialogues-preview">
              {dialoguesPreview.map((dialogue, index) => (
                <div key={index} className="preview-item">
                  <h4>{dialogue.title}</h4>
                  <p>{dialogue.description}</p>
                </div>
              ))}
              {dialoguesPreview.length === 0 && (
                <div className="preview-placeholder">
                  <p>{t('loadingDialogues', 'Carregando diálogos...')}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Stories Container */}
      <section className="content-container" id="stories-container">
        <div className="container-header">
          <h2>
            <i className="fas fa-book-open"></i> 
            <span>{t('navStories', 'Stories')}</span>
          </h2>
          <p>{t('featureStoriesDesc', 'Short engaging stories written specifically for your level.')}</p>
        </div>
        <div className="content-wrapper reverse">
          <div className="preview-example">
            <div id="stories-preview">
              {storiesPreview.map((story, index) => (
                <div key={index} className="preview-item">
                  <h4>{story.title}</h4>
                  <p>{story.description}</p>
                </div>
              ))}
              {storiesPreview.length === 0 && (
                <div className="preview-placeholder">
                  <p>{t('loadingStories', 'Carregando histórias...')}</p>
                </div>
              )}
            </div>
          </div>
          <div className="feature-image">
            <img 
              src="https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1073&q=80" 
              alt="Person reading a book"
            />
          </div>
        </div>
      </section>

      {/* Flashcards Container */}
      <section className="content-container" id="flashcards-container">
        <div className="container-header">
          <h2>
            <i className="fas fa-layer-group"></i> 
            <span>{t('navFlashcards', 'Flashcards')}</span>
          </h2>
          <p>{t('featureFlashcardsDesc', 'Smart flashcards with spaced repetition system.')}</p>
        </div>
        <div className="content-wrapper">
          <div className="feature-image">
            <img 
              src="https://images.unsplash.com/photo-1588072432836-e10032774350?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1172&q=80" 
              alt="Flashcards on a table"
            />
          </div>
          <div className="preview-example">
            <div id="flashcards-preview">
              {flashcardsPreview.map((flashcard, index) => (
                <div key={index} className="preview-item">
                  <h4>{flashcard.front}</h4>
                  <p>{flashcard.back}</p>
                </div>
              ))}
              {flashcardsPreview.length === 0 && (
                <div className="preview-placeholder">
                  <p>{t('loadingFlashcards', 'Carregando flashcards...')}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
